{"results": [{"id": "hp_doc_bf1e86308f2af4b9fbdcd6e92bb68e9a8c1980a5e102eb7a10f506921ecf89b1", "title": "Tuborg Brewery", "text": "Tuborg is a Danish brewing company founded in 1873 by Carl Frederik Tietgen. Since 1970 it has been part of the Carlsberg Group. The brewery was founded in Hellerup (Gentofte Municipality), a part of northern Copenhagen, Denmark.", "score": 34.9309}, {"id": "hp_doc_62bcd9c8aa2f592f2e5fdcb506da77c7d93e76b6bfde229a9b914b934a2dc3d3", "title": "Carl Frederik Tietgen", "text": "Carl Frederik Tietgen (19 March 1829 – 19 October 1901) was a Danish financier and industrialist. The founder of numerous prominent Danish companies, many of which are still in operation today, he played an important role in the industrialisation of Denmark. Notably also forming conglomerates, several of Tietgen's companies attained a monopoly-like status, which cemented their durability.", "score": 29.3431}, {"id": "hp_doc_1f1cbf1757be561bde398a719738b3440b2fdb7daf463892f7c7193f861694d2", "title": "Lauritz Peter Holmblad", "text": "Lauritz Peter Holmblad (8 July 1815 – 16 November 1890), usually referred to as L. P. Holmblad, was a Danish industrialist and philanthropist. He belonged to the circle around Carl Frederik Tietgen, co-founding several of his companies.", "score": 24.4859}], "remaining_searches": 2}
